/* generated by catalog.mjs from css.html, wow.html, webgl.html: [page, id, title, blurb, wow, platforms, section] */
window.CATALOG = [["css","c1","Barre de progression","La barre suit le scroll du bloc sans une ligne de JS : la timeline scroll() remplace la durée.",2,"wdm","Liées au scroll","#d1 .bar { position: sticky; top: -14px; height: 5px; margin: -14px -14px 10px; background: var(--tile); transform-origin: 0 50%; animation: d1 linear both; animation-timeline: scroll(); }\n@keyframes d1 { from { transform: scaleX(0); } }"],
["css","c2","Apparition à l'entrée","Chaque bloc a sa propre timeline view() : il se révèle pendant qu'il entre dans la zone visible.",3,"wm","Liées au scroll","#d2 i { animation: d2 linear both; animation-timeline: view(); animation-range: entry 0% cover 35%; }\n@keyframes d2 { from { opacity: 0; transform: translateY(30px) scale(.92); } }"],
["css","c3","En-tête qui se compacte","animation-range: 0 120px : l'en-tête rétrécit sur les 120 premiers pixels, puis ne bouge plus.",2,"wm","Liées au scroll","#d3 { padding-top: 0; }\n#d3 header { position: sticky; top: 0; z-index: 1; margin: 0 -14px 10px; padding: 28px 18px; font-size: 26px; font-weight: 600; background: var(--bg); animation: d3 linear both; animation-timeline: scroll(); animation-range: 0 120px; }\n@keyframes d3 { to { padding: 10px 18px; font-size: 15px; background: var(--tile); color: var(--tile-ink); } }"],
["css","c4","Parallaxe","Le calque intérieur glisse plus lentement que son cadre, piloté par la position du cadre dans le scroll.",4,"w","Liées au scroll","#d4 .ph { position: relative; height: 150px; margin-bottom: 14px; border-radius: 14px; overflow: hidden; }\n#d4 .layer { position: absolute; inset: -40% 0; background: radial-gradient(circle at 30% 40%, var(--l2), transparent 40%), radial-gradient(circle at 70% 60%, var(--tile), transparent 45%), var(--l3); animation: d4 linear both; animation-timeline: view(); }\n@keyframes d4 { from { transform: translateY(-25%); } to { transform: translateY(25%); } }"],
["css","c5","Carrousel qui met en avant","scroll-snap pour l'arrêt, view(inline) pour agrandir la carte centrale.",4,"wm","Liées au scroll","#d5 { display: flex; gap: 14px; width: 100%; overflow-x: auto; padding: 0 30%; scroll-snap-type: x mandatory; scrollbar-width: none; }\n#d5 b { flex: 0 0 40%; height: 150px; border-radius: 18px; background: var(--tile); scroll-snap-align: center; animation: d5 linear both; animation-timeline: view(inline); }\n@keyframes d5 { 0%, 100% { scale: .78; opacity: .45; } 50% { scale: 1; opacity: 1; } }"],
["css","c6","Points de carrousel natifs","::scroll-marker génère les points de navigation, :target-current allume le point actif. Zéro JS.",2,"wm","Liées au scroll","#d6 { display: flex; width: 86%; overflow-x: auto; scroll-snap-type: x mandatory; scroll-marker-group: after; scrollbar-width: none; scroll-behavior: smooth; }\n#d6 > div { flex: 0 0 100%; height: 130px; border-radius: 16px; background: var(--tile); color: var(--tile-ink); display: grid; place-items: center; font-size: 40px; scroll-snap-align: center; }\n#d6 > div::scroll-marker { content: \"\"; width: 10px; height: 10px; border-radius: 50%; background: var(--line); }\n#d6 > div::scroll-marker:target-current { background: var(--tile); width: 26px; border-radius: 5px; }\n#d6::scroll-marker-group { display: flex; gap: 8px; justify-content: center; margin-top: 14px; }"],
["css","c7","En-tête collé détecté","@container scroll-state(stuck: top) : le style change seulement quand l'élément sticky est réellement collé.",2,"wdm","Liées au scroll","#d7 header { position: sticky; top: -14px; z-index: 1; container-type: scroll-state; margin: 0 -14px 10px; }\n#d7 header > div { padding: 12px 18px; background: var(--bg); transition: background .3s, color .3s, border-radius .3s; }\n@container scroll-state(stuck: top) { #d7 header > div { background: var(--tile); color: var(--tile-ink); border-radius: 0 0 16px 16px; } }"],
["css","c8","Texte qui se remplit","Fond dégradé découpé au texte (background-clip: text), sa largeur suit le scroll ; sur un span en ligne, il remplit ligne après ligne.",4,"wm","Liées au scroll","#d8 p { font-size: 26px; line-height: 1.25; font-weight: 600; }\n#d8 span { color: transparent; -webkit-background-clip: text; background-clip: text; background-image: linear-gradient(var(--tile), var(--tile)), linear-gradient(var(--line), var(--line)); background-repeat: no-repeat; background-size: 100% 100%, 100% 100%; animation: d8 linear both; animation-timeline: view(); animation-range: cover 15% cover 55%; }\n@keyframes d8 { from { background-size: 0% 100%, 100% 100%; } }"],
["css","c9","View Transition : réordonner","document.startViewTransition() photographie avant et après, puis anime chaque élément nommé vers sa nouvelle place. La variante entre pages : @view-transition { navigation: auto }.",4,"wdm","Transitions d'état","#d9 { display: grid; grid-template-columns: repeat(3, 70px); gap: 10px; }\n#d9 b { height: 70px; border-radius: 14px; display: grid; place-items: center; background: var(--tile); color: var(--tile-ink); font-size: 22px; }\n#d9 b:nth-child(odd) { background: var(--l2); }\n::view-transition-group(*) { animation-duration: .5s; animation-timing-function: cubic-bezier(.2, .8, .2, 1); }"],
["css","c10","Changement de thème circulaire","Même API sur toute la page : la nouvelle capture s'ouvre en cercle depuis le point cliqué.",5,"wdm","Transitions d'état","html.vt-theme::view-transition-old(root) { animation: none; }\nhtml.vt-theme::view-transition-new(root) { animation: d10 .7s cubic-bezier(.2, .8, .2, 1); }\n@keyframes d10 { from { clip-path: circle(0 at var(--cx) var(--cy)); } to { clip-path: circle(150vmax at var(--cx) var(--cy)); } }"],
["css","c11","Popover avec entrée et sortie","@starting-style donne l'état de départ ; transition-behavior: allow-discrete laisse animer display jusqu'à la fin de la sortie.",2,"wdm","Transitions d'état","#b11 { anchor-name: --b11; }\n#p11 { position-anchor: --b11; position-area: bottom; inset: auto; margin: 8px 0 0; padding: 14px 18px; line-height: 1.9; border: 1px solid var(--line); border-radius: 14px; background: var(--panel); color: inherit;\n  opacity: 1; scale: 1; transition: opacity .25s, scale .25s, display .25s allow-discrete, overlay .25s allow-discrete; }\n#p11:not(:popover-open) { opacity: 0; scale: .92; }\n@starting-style { #p11:popover-open { opacity: 0; scale: .92; } }"],
["css","c12","Dialogue modal animé","Même recette sur <dialog>, avec le fond ::backdrop qui se fond aussi.",2,"wdm","Transitions d'état","#dlg12 { border: 1px solid var(--line); border-radius: 20px; padding: 24px; background: var(--panel); color: inherit;\n  opacity: 1; translate: 0; transition: opacity .3s, translate .3s, display .3s allow-discrete, overlay .3s allow-discrete; }\n#dlg12:not([open]) { opacity: 0; translate: 0 20px; }\n@starting-style { #dlg12[open] { opacity: 0; translate: 0 20px; } }\n#dlg12::backdrop { background: rgb(0 0 0 / .5); transition: background .3s, display .3s allow-discrete, overlay .3s allow-discrete; }\n@starting-style { #dlg12[open]::backdrop { background: rgb(0 0 0 / 0); } }"],
["css","c13","Animer vers height: auto","interpolate-size: allow-keywords rend enfin height: auto animable.",1,"wdm","Transitions d'état","#d13 { interpolate-size: allow-keywords; width: 80%; }\n#d13 .box { height: 0; overflow: hidden; transition: height .4s cubic-bezier(.2, .8, .2, 1); }\n#d13:has(:checked) .box { height: auto; }\n#d13 .box p { margin: 12px 0 0; padding: 14px; border-radius: 12px; background: var(--panel); }"],
["css","c14","Accordéon <details> animé","::details-content cible le contenu natif ; name commun = un seul ouvert à la fois.",1,"wdm","Transitions d'état","#d14 { interpolate-size: allow-keywords; width: 80%; }\n#d14 details { border-bottom: 1px solid var(--line); padding: 8px 0; }\n#d14 summary { cursor: pointer; font-weight: 600; }\n#d14 details::details-content { block-size: 0; overflow: hidden; transition: block-size .35s, content-visibility .35s allow-discrete; }\n#d14 details[open]::details-content { block-size: auto; }\n#d14 p { margin: 6px 0 2px; color: var(--muted); }"],
["css","c15","Interrupteur à ressort",":has(:checked) sur le parent, et un ressort écrit en linear() pour le dépassement.",2,"wdm","Transitions d'état","#d15 input { position: absolute; opacity: 0; }\n#d15 span { display: block; width: 76px; height: 42px; border-radius: 999px; background: var(--line); position: relative; cursor: pointer; transition: background .3s; }\n#d15 span::after { content: \"\"; position: absolute; left: 5px; top: 5px; width: 32px; height: 32px; border-radius: 50%; background: #fff; transition: translate .6s linear(0, .25 7%, .7 15%, 1.06 25%, 1.12 32%, 1.04 45%, .98 58%, 1.01 75%, 1); }\n#d15:has(:checked) span { background: var(--tile); }\n#d15:has(:checked) span::after { translate: 34px 0; }\n#d15:has(:focus-visible) span { outline: 2px solid var(--tile); outline-offset: 3px; }"],
["css","c16","Ressort contre ease","Survole la zone. En haut ease, en bas un ressort linear() : une courbe point par point, sans JS.",3,"wd","Transitions d'état","#d16 { align-content: center; gap: 22px; justify-items: start; padding: 0 30px; }\n#d16 b { width: 40px; height: 40px; border-radius: 50%; background: var(--l2); transition: translate .9s ease; }\n#d16 .spring { background: var(--tile); transition-timing-function: linear(0, .25 7%, .7 15%, 1.06 25%, 1.12 32%, 1.04 45%, .98 58%, 1.01 75%, 1); }\n#d16:hover b { translate: 260px 0; }"],
["css","c17","Infobulle ancrée","anchor-name + position-area : l'infobulle se place sur le bouton sans calcul de coordonnées.",1,"wd","Positionnement et structure","#d17 button { anchor-name: --b17; }\n#d17 .tip { position: absolute; position-anchor: --b17; position-area: top; margin-bottom: 10px; padding: 8px 12px; border-radius: 10px; background: var(--tile); color: var(--tile-ink); font-size: 14px; white-space: nowrap; opacity: 0; translate: 0 6px; transition: opacity .2s, translate .2s; pointer-events: none; }\n#d17 button:hover + .tip, #d17 button:focus-visible + .tip { opacity: 1; translate: 0; }"],
["css","c18","Onglets à indicateur glissant","L'onglet coché devient l'ancre ; l'indicateur suit ses bords avec anchor() et une transition.",2,"wdm","Positionnement et structure","#d18 { position: relative; display: inline-flex; gap: 4px; padding: 5px; border-radius: 999px; background: var(--panel); border: 1px solid var(--line); }\n#d18 label { position: relative; z-index: 1; padding: 9px 18px; border-radius: 999px; cursor: pointer; transition: color .3s; }\n#d18 input { position: absolute; opacity: 0; }\n#d18 label:has(:checked) { anchor-name: --t18; color: var(--tile-ink); }\n#d18 label:has(:focus-visible) { outline: 2px solid var(--tile); }\n#d18 .ind { position: absolute; position-anchor: --t18; top: anchor(top); bottom: anchor(bottom); left: anchor(left); right: anchor(right); border-radius: 999px; background: var(--tile); transition: left .35s cubic-bezier(.2, .8, .2, 1), right .35s cubic-bezier(.2, .8, .2, 1); }"],
["css","c19","Atténuer les voisins",":has(.t:hover) sur le parent : survoler une carte estompe les autres.",3,"wd","Positionnement et structure","#d19 { display: flex; gap: 12px; }\n#d19 .t { width: 70px; height: 110px; border-radius: 14px; background: var(--tile); transition: opacity .3s, scale .3s; }\n#d19:has(.t:hover) .t:not(:hover) { opacity: .35; scale: .94; }\n#d19 .t:hover { scale: 1.06; }"],
["css","c20","Requête de conteneur","Tire le coin du cadre : la carte change de mise en page selon la largeur de son conteneur, pas de l'écran.",1,"wdm","Positionnement et structure","#d20 { container-type: inline-size; resize: horizontal; overflow: hidden; width: 55%; min-width: 150px; max-width: 95%; padding: 12px; border: 1px dashed var(--line); border-radius: 12px; }\n#d20 .k { display: grid; gap: 10px; }\n#d20 .k b { height: 60px; border-radius: 10px; background: var(--tile); }\n#d20 .k p { margin: 4px 0 0; color: var(--muted); font-size: 14px; }\n@container (width > 260px) { #d20 .k { grid-template-columns: 90px 1fr; align-items: center; } #d20 .k b { height: 90px; } }"],
["css","c21","Cascade avec sibling-index()","Chaque élément connaît son rang : animation-delay: calc(sibling-index() * 60ms), plus besoin de --i écrit à la main.",3,"wdm","Positionnement et structure","#d21 { display: flex; gap: 8px; align-items: end; height: 120px; }\n#d21 i { width: 22px; height: 100%; border-radius: 8px; background: var(--tile); transform-origin: bottom; animation: d21 .7s cubic-bezier(.2, .8, .2, 1) both; animation-delay: calc(sibling-index() * 60ms); }\n@keyframes d21 { from { scale: 1 0; opacity: 0; } }"],
["css","c22","Champ qui s'ajuste","field-sizing: content : le champ grandit avec ce qu'on tape.",1,"wdm","Positionnement et structure","#d22 { field-sizing: content; min-width: 8ch; max-width: 90%; padding: 12px 18px; border-radius: 12px; border: 1px solid var(--line); background: var(--panel); color: inherit; font-size: 18px; transition: border-color .2s; }\n#d22:focus { outline: none; border-color: var(--tile); }"],
["css","c23","Titres équilibrés","À gauche le retour à la ligne habituel, à droite text-wrap: balance : des lignes de longueur égale, sans orphelin.",1,"wm","Positionnement et structure","#d23 { grid-template-columns: 1fr 1fr; gap: 18px; padding: 0 18px; }\n#d23 p { font-size: 20px; font-weight: 600; line-height: 1.2; padding: 10px; border: 1px dashed var(--line); border-radius: 10px; margin: 0; }\n#d23 .bal { text-wrap: balance; }"],
["css","c24","Formes de coin","corner-shape change la forme de l'arrondi : rond, squircle, creusé, biseauté. Elle s'anime au survol.",2,"wdm","Positionnement et structure","#d24 { grid-template-columns: repeat(4, 74px); gap: 12px; }\n#d24 b { height: 74px; display: grid; place-items: end center; padding-bottom: 6px; font: 500 11px var(--mono); border-radius: 26px; background: var(--tile); color: var(--tile-ink); transition: border-radius .4s; }\n#d24 b:hover { border-radius: 37px; }"],
["css","c25","Bordure dégradée qui tourne","@property type l'angle d'un dégradé conique : le navigateur peut alors l'interpoler.",4,"wd","Mouvement","@property --a25 { syntax: \"<angle>\"; inherits: false; initial-value: 0deg; }\n#d25 { padding: 40px 48px; border-radius: 20px; border: 2px solid transparent; background: linear-gradient(var(--panel), var(--panel)) padding-box, conic-gradient(from var(--a25), var(--tile), transparent 30%, transparent 60%, var(--tile)) border-box; animation: d25 3s linear infinite; }\n@keyframes d25 { to { --a25: 360deg; } }"],
["css","c26","Compteur en CSS pur","Un entier typé avec @property, animé, puis affiché par counter().",3,"wm","Mouvement","@property --n26 { syntax: \"<integer>\"; inherits: false; initial-value: 0; }\n#d26 { --n26: 2026; counter-reset: n var(--n26); font-size: 72px; font-weight: 700; font-variant-numeric: tabular-nums; animation: d26 2s cubic-bezier(.2, .8, .2, 1) both; }\n#d26::after { content: counter(n); }\n@keyframes d26 { from { --n26: 0; } }"],
["css","c27","Fond en dégradé maillé","Trois dégradés radiaux dont les positions, typées en @property, dérivent lentement.",4,"w","Mouvement","@property --x27 { syntax: \"<percentage>\"; inherits: false; initial-value: 20%; }\n@property --y27 { syntax: \"<percentage>\"; inherits: false; initial-value: 20%; }\n#d27 { background: radial-gradient(at var(--x27) 30%, var(--l2), transparent 55%), radial-gradient(at 75% var(--y27), var(--tile), transparent 50%), radial-gradient(at calc(100% - var(--x27)) 90%, var(--l1), transparent 55%), var(--bg); animation: d27 7s ease-in-out infinite alternate; }\n@keyframes d27 { to { --x27: 80%; --y27: 85%; } }"],
["css","c28","Mouvement le long d'un tracé","offset-path + offset-distance : l'élément suit une courbe et s'oriente dessus.",3,"w","Mouvement","#d28 svg { position: absolute; width: 300px; height: 160px; } #d28 path { fill: none; stroke: var(--line); stroke-width: 2; stroke-dasharray: 6 6; }\n#d28 b { position: absolute; left: calc(50% - 150px); top: calc(50% - 80px); width: 26px; height: 16px; border-radius: 4px 12px 12px 4px; background: var(--tile); offset-path: path(\"M20,120 C80,0 150,170 280,40\"); animation: d28 2.6s ease-in-out infinite alternate; }\n@keyframes d28 { from { offset-distance: 0%; } to { offset-distance: 100%; } }"],
["css","c29","Transformations séparées","translate, rotate, scale sont des propriétés à part : une rotation infinie et un survol se cumulent sans s'écraser.",2,"wd","Mouvement","#d29 { width: 80px; height: 80px; border-radius: 22px; background: var(--tile); animation: d29 6s linear infinite; transition: translate .4s cubic-bezier(.2, .8, .2, 1), scale .4s cubic-bezier(.2, .8, .2, 1); }\n#d29:hover { translate: 0 -16px; scale: 1.15; }\n@keyframes d29 { to { rotate: 1turn; } }"],
["css","c30","Morphing clip-path","Deux polygon() au même nombre de points s'interpolent : étoile vers décagone.",3,"w","Mouvement","#d30 { width: 130px; height: 130px; background: var(--tile); clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); animation: d30 2.4s cubic-bezier(.6, 0, .4, 1) infinite alternate; }\n@keyframes d30 { to { clip-path: polygon(50% 0, 79% 10%, 98% 35%, 98% 65%, 79% 91%, 50% 100%, 21% 91%, 2% 65%, 2% 35%, 21% 10%); rotate: 36deg; } }"],
["css","c31","Morphing de tracé SVG","La propriété d se règle et s'anime en CSS, tant que les deux tracés ont les mêmes commandes.",4,"w","Mouvement","#d31 { width: 150px; } #d31 path { fill: var(--tile); d: path(\"M50 8 C78 8 92 30 92 50 C92 76 72 92 50 92 C24 92 8 74 8 50 C8 24 26 8 50 8Z\"); animation: d31 3s ease-in-out infinite alternate; }\n@keyframes d31 { to { d: path(\"M50 18 C88 2 96 40 84 58 C70 90 64 98 44 86 C14 74 2 58 14 34 C24 14 34 22 50 18Z\"); } }"],
["css","c32","Bande défilante en CSS","Contenu doublé et translation de -50 % en boucle ; mask-image estompe les bords, le survol met en pause.",3,"wm","Mouvement","#d32 { width: 100%; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 15%, #000 85%, transparent); }\n#d32 .trk { display: flex; gap: 12px; width: max-content; animation: d32 12s linear infinite; }\n#d32:hover .trk { animation-play-state: paused; }\n#d32 b { padding: 14px 24px; border-radius: 999px; background: var(--panel); border: 1px solid var(--line); font-size: 18px; }\n@keyframes d32 { to { translate: calc(-50% - 6px) 0; } }"],
["css","c33","Carte qui se retourne","transform-style: preserve-3d et backface-visibility: hidden : deux faces, une rotation.",3,"wd","Mouvement","#d33 { width: 200px; height: 130px; perspective: 800px; }\n#d33 .in { position: relative; height: 100%; transform-style: preserve-3d; transition: transform .7s cubic-bezier(.2, .8, .2, 1); }\n#d33:hover .in { transform: rotateY(180deg); }\n#d33 .f { position: absolute; inset: 0; border-radius: 18px; display: grid; place-items: center; font-size: 22px; background: var(--panel); border: 1px solid var(--line); backface-visibility: hidden; }\n#d33 .b { background: var(--tile); color: var(--tile-ink); transform: rotateY(180deg); }"],
["css","c34","Verre dépoli","backdrop-filter floute ce qui passe derrière la carte ; une bordure claire et une teinte légère font le reste.",4,"wdm","Mouvement","#d34 i { position: absolute; width: 120px; height: 120px; border-radius: 50%; background: var(--tile); animation: d34 5s ease-in-out infinite alternate; }\n#d34 i + i { background: var(--l2); animation-direction: alternate-reverse; }\n#d34 .g { position: relative; padding: 34px 54px; border-radius: 22px; font-size: 22px; background: color-mix(in srgb, var(--panel) 35%, transparent); border: 1px solid rgb(255 255 255 / .18); backdrop-filter: blur(18px) saturate(1.4); }\n@keyframes d34 { from { translate: -110px -40px; } to { translate: 110px 40px; } }"],
["css","c35","Machine à écrire","steps(22) sur la largeur en ch d'un texte mono de 22 caractères, et un curseur qui clignote.",3,"w","Texte, boutons et chargement","#d35 { font: 22px var(--mono); width: 22ch; white-space: nowrap; overflow: hidden; border-right: 2px solid var(--tile); animation: d35a 2.4s steps(22) both, d35b .8s step-end infinite; }\n@keyframes d35a { from { width: 0; } }\n@keyframes d35b { 50% { border-color: transparent; } }"],
["css","c36","Texte scintillant","Le reflet des états « l'IA réfléchit » : dégradé découpé au texte qui glisse en boucle.",3,"wdm","Texte, boutons et chargement","#d36 { font-size: 26px; font-weight: 600; color: transparent; background: linear-gradient(90deg, var(--muted) 35%, #fff 50%, var(--muted) 65%) 0 0 / 300% 100%; -webkit-background-clip: text; background-clip: text; animation: d36 2s linear infinite; }\n@keyframes d36 { from { background-position: 100% 0; } to { background-position: 0 0; } }"],
["css","c37","Soulignement qui glisse","Un fond d'un trait de 2 px dont la taille passe de 0 à 100 % ; il entre par la gauche et sort par la droite.",2,"wd","Texte, boutons et chargement","#d37 { display: flex; gap: 26px; font-size: 22px; }\n#d37 a { color: inherit; text-decoration: none; background: linear-gradient(currentColor, currentColor) no-repeat 100% 100% / 0 2px; transition: background-size .35s cubic-bezier(.2, .8, .2, 1); }\n#d37 a:hover, #d37 a:focus-visible { background-size: 100% 2px; background-position-x: 0; }"],
["css","c38","Bouton qui se remplit","Le fond monte depuis le bas avec background-size ; la flèche avance d'un cran.",2,"wd","Texte, boutons et chargement","#d38 { display: inline-flex; gap: 10px; padding: 14px 26px; border-radius: 999px; border: 1px solid var(--tile); color: inherit; text-decoration: none; font-size: 17px; background: linear-gradient(var(--tile), var(--tile)) no-repeat 0 100% / 100% 0; transition: background-size .35s cubic-bezier(.2, .8, .2, 1), color .35s; }\n#d38:hover, #d38:focus-visible { background-size: 100% 100%; color: var(--tile-ink); }\n#d38 span { transition: translate .35s cubic-bezier(.2, .8, .2, 1); } #d38:hover span { translate: 5px 0; }"],
["css","c39","Squelette de chargement","Formes grises et reflet qui balaie (background-position), le temps que le contenu arrive.",1,"wdm","Texte, boutons et chargement","#d39 { display: flex; gap: 14px; align-items: center; width: 75%; }\n#d39 > div { flex: 1; display: grid; gap: 10px; }\n#d39 b { display: block; height: 14px; border-radius: 7px; background: linear-gradient(90deg, var(--panel) 30%, var(--line) 50%, var(--panel) 70%) 0 0 / 300% 100%; animation: d39 1.4s linear infinite; }\n#d39 .av { width: 56px; height: 56px; border-radius: 50%; } #d39 .s { width: 60%; }\n@keyframes d39 { from { background-position: 100% 0; } to { background-position: 0 0; } }"],
["css","c40","Anneau de chargement","Un dégradé conique troué par un mask radial : un anneau à queue dégradée, une seule balise.",1,"wdm","Texte, boutons et chargement","#d40 { width: 64px; aspect-ratio: 1; border-radius: 50%; background: conic-gradient(transparent 15%, var(--tile)); mask: radial-gradient(farthest-side, transparent calc(100% - 8px), #000 calc(100% - 7px)); animation: d40 .9s linear infinite; }\n@keyframes d40 { to { rotate: 1turn; } }"],
["wow","w1","Palette de commandes","Entrée en fondu, léger zoom et flou qui se dissipe ; les résultats arrivent en cascade de 35 ms.",4,"wd","Application de bureau","#d1 .pal { position: absolute; top: 18px; width: 78%; padding: 8px; border-radius: 16px; background: var(--panel); border: 1px solid var(--line); box-shadow: 0 30px 60px -20px rgb(0 0 0 / .6);\n  opacity: 0; scale: .96; filter: blur(6px); translate: 0 -8px; pointer-events: none; transition: opacity .22s, scale .22s var(--ease-out), filter .22s, translate .22s var(--ease-out); }\n#d1.open .pal { opacity: 1; scale: 1; filter: none; translate: 0; pointer-events: auto; }\n#d1 .q { margin: 0 0 6px; padding: 8px 10px; border-bottom: 1px solid var(--line); color: var(--muted); }\n#d1 .pal div { padding: 7px 10px; border-radius: 9px; font-size: 14px; opacity: 0; translate: 0 6px; transition: opacity .25s, translate .25s var(--ease-out); transition-delay: calc(var(--i) * 35ms); }\n#d1.open .pal div { opacity: 1; translate: 0; }\n#d1 .pal div:first-of-type { background: color-mix(in srgb, var(--tile) 22%, transparent); }"],
["wow","w3","Dock qui grossit","CSS seul : l'icône survolée grossit, ses voisines aussi un peu, grâce à :has(+ i:hover) pour celle d'avant.",3,"d","Application de bureau","#d3 { display: flex; align-items: end; gap: 8px; padding: 10px 12px; border-radius: 20px; background: color-mix(in srgb, var(--panel) 70%, transparent); border: 1px solid var(--line); }\n#d3 i { width: 44px; height: 44px; border-radius: 12px; background: var(--tile); transform-origin: bottom; transition: scale .2s var(--ease-out), margin .2s var(--ease-out); }\n#d3 i:nth-child(3n) { background: var(--l2); } #d3 i:nth-child(3n+1) { background: var(--l1); }\n#d3 i:hover { scale: 1.6; margin: 0 14px; }\n#d3 i:has(+ i:hover), #d3 i:hover + i { scale: 1.28; margin: 0 6px; }"],
["wow","w4","Fenêtre qui naît de son icône","Icône et fenêtre portent le même view-transition-name : le navigateur morphe l'une en l'autre.",4,"wd","Application de bureau","#d4 .ico { width: 58px; height: 58px; border-radius: 16px; border: 0; background: var(--tile); view-transition-name: w4win; }\n#d4 .win { display: none; width: 82%; height: 160px; padding: 12px 14px; border-radius: 16px; background: var(--panel); border: 1px solid var(--line); }\n#d4 .win span { display: inline-block; width: 10px; height: 10px; margin-right: 6px; border-radius: 50%; background: var(--line); }\n#d4.open .ico { display: none; } #d4.open .win { display: block; view-transition-name: w4win; }\n::view-transition-group(w4win) { animation-duration: .45s; animation-timing-function: cubic-bezier(.2, .9, .2, 1); }"],
["wow","w5","Pile de notifications","Repliées en pile (échelle et décalage), elles se déploient au survol. Transitions seules.",3,"wd","Application de bureau","#d5 { position: relative; width: 72%; height: 190px; }\n#d5 b { position: absolute; left: 0; right: 0; bottom: 0; height: 52px; padding: 0 16px; display: flex; align-items: center; border-radius: 14px; background: var(--panel); border: 1px solid var(--line); font-weight: 500; transition: translate .35s var(--ease-out), scale .35s var(--ease-out), opacity .35s; }\n#d5 b:nth-child(1) { z-index: 3; } #d5 b:nth-child(2) { z-index: 2; translate: 0 -10px; scale: .94; } #d5 b:nth-child(3) { z-index: 1; translate: 0 -20px; scale: .88; opacity: .7; }\n#d5:hover b:nth-child(2) { translate: 0 -62px; scale: 1; } #d5:hover b:nth-child(3) { translate: 0 -124px; scale: 1; opacity: 1; }"],
["wow","w8","Faisceau sur la bordure","Un arc lumineux court le long du champ (@property + dégradé conique) : le signe « l'agent travaille ».",4,"wd","Application de bureau","@property --a8 { syntax: \"<angle>\"; inherits: false; initial-value: 0deg; }\n#d8 { display: block; width: 80%; padding: 2px; border-radius: 16px; background: conic-gradient(from var(--a8), transparent 0 72%, var(--tile) 86%, #fff 90%, transparent 94%), var(--line); animation: d8 2.6s linear infinite; box-shadow: 0 0 40px -12px var(--tile); }\n#d8 input { width: 100%; padding: 14px 16px; border: 0; border-radius: 14px; background: var(--panel); color: inherit; font-size: 16px; outline: none; }\n@keyframes d8 { to { --a8: 360deg; } }"],
["wow","w10","Envoyer, charger, validé","Un seul bouton change d'état : il se rétracte en cercle qui tourne, puis trace une coche.",3,"wdm","Application de bureau","#d10 { position: relative; width: 180px; height: 52px; border: 0; border-radius: 26px; background: var(--tile); color: var(--tile-ink); font-weight: 600; transition: width .35s var(--ease-out), background .3s; }\n#d10 svg { position: absolute; inset: 0; margin: auto; width: 26px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-dasharray: 24; stroke-dashoffset: 24; }\n#d10[data-s=\"load\"], #d10[data-s=\"done\"] { width: 52px; } #d10[data-s] span { opacity: 0; }\n#d10[data-s=\"load\"] { background: transparent; border: 3px solid var(--line); border-top-color: var(--tile); animation: d10 .8s linear infinite; }\n#d10[data-s=\"done\"] svg { stroke-dashoffset: 0; transition: stroke-dashoffset .4s .1s var(--ease-out); }\n@keyframes d10 { to { rotate: 1turn; } }"],
["wow","w11","Barre latérale repliable","La largeur passe de la barre complète au rail d'icônes ; les libellés s'effacent un peu avant.",2,"d","Application de bureau","#d11 { display: flex; width: 88%; height: 170px; border-radius: 14px; border: 1px solid var(--line); overflow: hidden; }\n#d11 nav { width: 160px; padding: 8px; background: var(--panel); display: grid; align-content: start; gap: 4px; transition: width .3s var(--ease-out); }\n#d11 nav button { justify-self: start; width: 36px; height: 30px; border: 0; border-radius: 8px; background: transparent; }\n#d11 a { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: 9px; white-space: nowrap; }\n#d11 a:first-of-type { background: color-mix(in srgb, var(--tile) 22%, transparent); }\n#d11 i { flex: none; width: 18px; height: 18px; border-radius: 6px; background: var(--tile); }\n#d11 span { transition: opacity .15s; }\n#d11.mini nav { width: 52px; } #d11.mini span { opacity: 0; }\n#d11 section { flex: 1; background: repeating-linear-gradient(var(--bg) 0 22px, var(--line) 22px 23px); }"],
["wow","w12","Menu contextuel au curseur","Clic droit dans la zone : le menu s'ouvre là où est le pointeur, en grandissant depuis ce coin (transform-origin).",2,"d","Application de bureau","#d12 p { color: var(--muted); }\n#d12 .ctx { position: absolute; left: var(--x, 50%); top: var(--y, 50%); min-width: 160px; padding: 6px; border-radius: 12px; background: var(--panel); border: 1px solid var(--line); box-shadow: 0 20px 40px -14px rgb(0 0 0 / .6);\n  transform-origin: 0 0; opacity: 0; scale: .85; pointer-events: none; transition: opacity .14s, scale .18s var(--ease-out); }\n#d12.open .ctx { opacity: 1; scale: 1; pointer-events: auto; }\n#d12 .ctx div { padding: 7px 10px; border-radius: 8px; font-size: 14px; } #d12 .ctx div:hover { background: color-mix(in srgb, var(--tile) 22%, transparent); }"],
["wow","w9","Odomètre","Chaque chiffre est une colonne 0–9 qui roule jusqu'à sa valeur ; chiffres tabulaires, rien ne saute.",3,"wdm","Application de bureau","#d9 { display: flex; font-size: 64px; font-weight: 700; line-height: 1; height: 1em; overflow: hidden; font-variant-numeric: tabular-nums; }\n#d9 .col { display: flex; flex-direction: column; transition: translate .9s cubic-bezier(.2, .9, .2, 1); transition-delay: calc(var(--i) * 60ms); }"],
["wow","w17","Cloche et pastille","La cloche oscille, la pastille saute avec un ressort linear(). Rejoué à chaque notification.",2,"wdm","Application de bureau","#d17 { position: relative; width: 64px; height: 64px; border-radius: 18px; border: 1px solid var(--line); background: var(--panel); }\n#d17 svg { width: 30px; fill: none; stroke: currentColor; stroke-width: 1.8; transform-origin: 50% 10%; }\n#d17 b { position: absolute; top: -6px; right: -6px; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px; background: var(--tile); color: var(--tile-ink); font-size: 12px; display: grid; place-items: center; }\n#d17.ring svg { animation: d17a .7s ease-in-out; }\n#d17.ring b { animation: d17b .6s linear(0, .25 7%, .7 15%, 1.06 25%, 1.12 32%, 1.04 45%, .98 58%, 1.01 75%, 1); }\n@keyframes d17a { 20% { rotate: 16deg; } 40% { rotate: -14deg; } 60% { rotate: 8deg; } 80% { rotate: -4deg; } }\n@keyframes d17b { from { scale: 0; } }"],
["wow","w2","Verre liquide qui réfracte","Une lentille déforme ce qui passe dessous : backdrop-filter: url(#filtre) avec un déplacement SVG, plus un reflet de bord. Chromium seulement ; ailleurs, simple flou.",5,"wdm","Site web","#d2 { background: repeating-linear-gradient(115deg, var(--bg) 0 18px, color-mix(in srgb, var(--tile) 25%, var(--bg)) 18px 22px); }\n#d2 .bg { font-size: 28px; font-weight: 700; line-height: 1.15; text-align: center; margin: 0; }\n#d2 .lens { position: absolute; left: 0; top: 0; width: 150px; height: 110px; border-radius: 40px; translate: var(--x, 120px) var(--y, 50px);\n  backdrop-filter: url(#w2f) blur(.5px) saturate(1.6) brightness(1.1); -webkit-backdrop-filter: blur(6px) saturate(1.6);\n  box-shadow: inset 0 1px 1px rgb(255 255 255 / .7), inset 0 -10px 20px rgb(255 255 255 / .08), 0 12px 30px -10px rgb(0 0 0 / .5); border: 1px solid rgb(255 255 255 / .25); }"],
["wow","w6","Îlot qui se transforme","Une pastille noire qui s'étire pour montrer un état puis un lecteur, avec un léger dépassement (cubic-bezier au-delà de 1).",5,"wdm","Site web","#d6 { position: relative; width: 120px; height: 36px; border-radius: 18px; background: #000; color: #fff; overflow: hidden; animation: d6 6s cubic-bezier(.3, 1.3, .5, 1) infinite; }\n@keyframes d6 { 0%, 12% { width: 120px; height: 36px; border-radius: 18px; } 22%, 45% { width: 290px; height: 58px; border-radius: 29px; } 55%, 85% { width: 300px; height: 130px; border-radius: 32px; } 95%, 100% { width: 120px; height: 36px; border-radius: 18px; } }\n#d6 > div { position: absolute; inset: 0; padding: 0 22px; display: flex; align-items: center; gap: 10px; white-space: nowrap; opacity: 0; }\n#d6 .a { animation: d6a 6s infinite; } #d6 .a i { width: 10px; height: 10px; border-radius: 50%; background: #5fd38a; }\n#d6 .b { flex-direction: column; align-items: start; justify-content: center; gap: 4px; animation: d6b 6s infinite; } #d6 .b span { color: #aaa; font-size: 14px; }\n#d6 .b em { width: 100%; height: 4px; border-radius: 2px; background: linear-gradient(90deg, #fff 40%, #444 40%); margin-top: 8px; }\n@keyframes d6a { 0%, 20% { opacity: 0; } 27%, 42% { opacity: 1; } 48%, 100% { opacity: 0; } }\n@keyframes d6b { 0%, 56% { opacity: 0; } 63%, 82% { opacity: 1; } 88%, 100% { opacity: 0; } }"],
["wow","w7","Réponse en streaming","Chaque mot arrive flou puis net, décalé de 70 ms : le rythme d'une réponse d'IA, sans saccade.",4,"wdm","Site web","#d7 { width: 84%; font-size: 20px; line-height: 1.45; }\n#d7 span { display: inline-block; white-space: pre; animation: d7 .45s ease-out both; animation-delay: calc(var(--i) * 70ms); }\n@keyframes d7 { from { opacity: 0; filter: blur(6px); translate: 0 4px; } }"],
["wow","w13","Confettis de réussite","Une salve de particules en canvas (gravité, rotation, fondu) lancée depuis le bouton. Rien sous mouvement réduit.",4,"wdm","Site web","#d13 canvas { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }\n#d13 button { position: relative; padding: 12px 22px; background: var(--tile); color: var(--tile-ink); border: 0; font-weight: 600; }"],
["wow","w14","Titre éclairé au curseur","Deux copies du titre : la seconde, en couleur, n'apparaît que dans un disque qui suit le pointeur (mask-image radial).",4,"wd","Site web","#d14 p { grid-area: 1 / 1; margin: 0 24px; font-size: 40px; font-weight: 700; line-height: 1.05; color: var(--line); text-align: center; }\n#d14 .lit { color: var(--tile); mask-image: radial-gradient(circle 110px at var(--x, 50%) var(--y, 50%), #000 30%, transparent 100%); -webkit-mask-image: radial-gradient(circle 110px at var(--x, 50%) var(--y, 50%), #000 30%, transparent 100%); }"],
["wow","w15","Paquet de cartes","Clic : la carte du dessus s'envole puis repasse dessous ; les autres remontent d'un cran.",4,"wdm","Site web","#d15 { position: relative; width: 180px; height: 120px; cursor: pointer; }\n#d15 b { position: absolute; inset: 0; border-radius: 18px; display: grid; place-items: center; font-size: 34px; background: var(--tile); color: var(--tile-ink); box-shadow: 0 10px 24px -10px rgb(0 0 0 / .6); transition: translate .4s var(--ease-out), scale .4s var(--ease-out), rotate .4s var(--ease-out); }\n#d15 b:nth-child(2) { background: var(--l2); } #d15 b:nth-child(3) { background: var(--l1); } #d15 b:nth-child(4) { background: var(--l3); }\n#d15 b:nth-last-child(2) { translate: 0 -10px; scale: .95; rotate: -3deg; } #d15 b:nth-last-child(3) { translate: 0 -20px; scale: .9; rotate: 3deg; } #d15 b:nth-last-child(n+4) { translate: 0 -28px; scale: .85; }\n#d15 b.out { animation: d15 .5s var(--ease-out); }\n@keyframes d15 { 50% { translate: 0 -140px; rotate: -12deg; } }"],
["wow","w16","Vague de graisse","Une police variable : chaque lettre passe de fin à gras, décalée de sa voisine. La vague traverse le mot.",4,"w","Site web","#d16 { font-family: var(--serif); font-size: 76px; margin: 0; }\n#d16 span { display: inline-block; font-weight: 200; animation: d16 2.4s ease-in-out infinite; animation-delay: calc(var(--i) * 120ms); }\n@keyframes d16 { 50% { font-weight: 900; } }"],
["wow","w18","Courbe qui se trace","Le tracé se dessine (stroke-dashoffset) et un point lumineux suit sa tête sur le même chemin (offset-path).",3,"wd","Site web","#d18 svg { width: 300px; overflow: visible; }\n#d18 path { fill: none; stroke: var(--tile); stroke-width: 3; stroke-linecap: round; stroke-dasharray: 420; animation: d18a 3s cubic-bezier(.4, 0, .2, 1) infinite; }\n#d18 b { position: absolute; left: calc(50% - 150px); top: calc(50% - 60px); width: 12px; height: 12px; margin: -6px; border-radius: 50%; background: #fff; box-shadow: 0 0 16px 4px var(--tile); offset-path: path(\"M0,100 C40,90 60,40 100,60 S160,110 200,50 S260,10 300,20\"); offset-rotate: 0deg; animation: d18b 3s cubic-bezier(.4, 0, .2, 1) infinite; }\n@keyframes d18a { from { stroke-dashoffset: 420; } 80%, to { stroke-dashoffset: 0; } }\n@keyframes d18b { from { offset-distance: 0%; } 80%, to { offset-distance: 100%; } }"],
["wow","w19","Grille de points qui réagit","Canvas : chaque point fuit le pointeur puis revient par un ressort. Sans pointeur, une source invisible se promène.",5,"wd","Site web","#d19 canvas { position: absolute; inset: 0; width: 100%; height: 100%; }"],
["wow","w20","Du squelette au contenu","Le contenu remplace le squelette en fondu, en sortant d'un léger flou : l'œil ne voit pas de saut.",2,"wdm","Site web","#d20 { display: grid; width: 75%; }\n#d20 > div { grid-area: 1 / 1; display: flex; gap: 14px; align-items: center; }\n#d20 > div > div { flex: 1; display: grid; gap: 8px; }\n#d20 .sk b { display: block; height: 14px; border-radius: 7px; background: var(--panel); } #d20 .sk .av, #d20 .ct i { width: 56px; height: 56px; border-radius: 50%; flex: none; } #d20 .sk .s { width: 60%; }\n#d20 .ct i { background: linear-gradient(135deg, var(--tile), var(--l2)); } #d20 .ct span { color: var(--muted); font-size: 14px; }\n#d20 .sk { animation: d20a 4s infinite; } #d20 .ct { animation: d20b 4s infinite; }\n@keyframes d20a { 0%, 40% { opacity: 1; } 50%, 90% { opacity: 0; } 100% { opacity: 1; } }\n@keyframes d20b { 0%, 40% { opacity: 0; filter: blur(8px); } 55%, 90% { opacity: 1; filter: blur(0); } 100% { opacity: 0; filter: blur(8px); } }"],
["webgl","s1","Aurore · héros de SaaS","Lumière douce derrière un titre centré. Le bas du fond s'efface pour que la rangée de logos reste lisible. Le choix le plus sûr des trois.",5,"wd","Shaders","float n = sin(p.x * 3.0 + t * .4 + sin(p.y * 2.0 + t * .3) * 1.5);\nfloat band = smoothstep(.0, .9, 1.0 - abs(p.y - .15 * n - .1) * 2.2);\nvec3 c = mix(vec3(.02, .05, .08), mix(A, B, .5 + .5 * sin(p.x + t * .2)), band);\nc += A * .15 * exp(-3.0 * abs(p.y + .3));\no = vec4(c, 1);"],
["webgl","s2","Chrome liquide · page de lancement","Matière métallique à droite, texte sur un voile sombre à gauche. Pour une annonce, une liste d'attente, un produit physique.",5,"wd","Shaders","vec2 q = vec2(fbm(p * 1.6 + t * .1), fbm(p * 1.6 + 3.1));\nfloat f = fbm(p * 1.6 + 2.0 * q + t * .15);\nfloat h = pow(.5 + .5 * sin(f * 12.0), 3.0);\no = vec4(mix(vec3(.08, .09, .1), vec3(.92), h) + A * .25 * q.x, 1);"],
["webgl","s3","Courbes de niveau · section de chiffres","Relief topographique sur la moitié droite, fondu vers le texte. Sobre : marche pour un rapport, une page « à propos », un produit de données.",5,"wd","Shaders","float h = fbm(p * 1.4 + vec2(t * .05, 0)) * 10.0;\nfloat l = abs(fract(h) - .5) / fwidth(h);\nfloat major = step(.5, fract(h / 5.0 + .1));\no = vec4(vec3(.04) + mix(B, A, major) * (1.0 - smoothstep(.0, 1.2, l)), 1);"],
["webgl","s4","Dégradé maillé · héros fintech","Trois pôles de couleur qui dérivent et se mélangent, avec un grain fin. Le fond « vivant mais calme » des sites de paiement et d'infrastructure.",5,"wd","Shaders","float s = t * .15; vec2 q = p * .6 + .15 * vec2(fbm(p * 1.5 + s), fbm(p * 1.5 - s));\nvec2 c1 = vec2(sin(s) * .8, cos(s * 1.3) * .5), c2 = vec2(cos(s * .7 + 2.0) * .9, sin(s * .9) * .6), c3 = vec2(sin(s * 1.1 + 4.0) * .7, cos(s * .6 + 1.0) * .7);\nfloat w1 = 1.0 / (.15 + dot(q - c1, q - c1)), w2 = 1.0 / (.15 + dot(q - c2, q - c2)), w3 = 1.0 / (.15 + dot(q - c3, q - c3));\nvec3 c = (A * w1 + B * w2 + vec3(.97, .45, .55) * w3) / (w1 + w2 + w3);\no = vec4(c + (hash(gl_FragCoord.xy + fract(t) * 91.0) - .5) * .08, 1);"],
["webgl","s5","Orbe · assistant vocal","Une sphère liquide au centre, bord qui ondule. Représente « l'IA écoute » sans visage. Le texte reste dessous, hors de la matière.",5,"wd","Shaders","float r = length(p); vec2 q = p * 1.8;\nfloat n = fbm(q + vec2(t * .3, -t * .2) + fbm(q * 1.5 - t * .2));\nfloat e = .55 + .05 * sin(atan(p.y, p.x) * 3.0 + t) + .08 * (n - .5), ins = smoothstep(e, e - .02, r);\nvec3 core = mix(A, B, n) * (.5 + .9 * n) + pow(max(0.0, 1.0 - r / e), 3.0) * .6;\nvec3 c = vec3(.012) + core * ins + mix(A, B, .5) * exp(-max(r - e, 0.0) * 6.0) * .45 * (1.0 - ins) + smoothstep(.025, .0, abs(r - e)) * .5 * B;\no = vec4(c, 1);"],
["webgl","s11","Rayons · annonce de lancement","Faisceaux qui tombent du haut et éclairent le titre. Effet « révélation » pour un keynote ou une sortie majeure.",5,"wd","Shaders","vec2 d = p - vec2(0, 1.3); float a = atan(d.x, -d.y), r = length(d);\nfloat b = (.5 + .5 * sin(a * 14.0 + t * .3 + sin(a * 5.0 - t * .2) * 2.0)) * (.5 + .5 * sin(a * 23.0 - t * .5));\nfloat fall = exp(-r * .8) * smoothstep(1.1, .0, abs(a));\no = vec4(vec3(.015, .015, .02) + mix(B, A, b) * b * fall * 1.6 + A * .3 * exp(-r * 2.2), 1);"],
["webgl","s6","Globe pointillé · réseau mondial","Sphère en points qui tourne, continents en bruit. Pour une infrastructure, un CDN, une présence internationale.",5,"wd","Shaders","float R0 = .78, r2 = dot(p, p); vec3 c = vec3(.015) + A * .18 * exp(-abs(sqrt(r2) - R0) * 9.0);\nif (r2 < R0 * R0) { vec3 n = vec3(p, sqrt(R0 * R0 - r2)) / R0, v = n; float a = t * .2; v.xz = mat2(cos(a), -sin(a), sin(a), cos(a)) * v.xz;\n  float lat = asin(v.y), lon = atan(v.x, v.z); vec2 g = vec2(lon, lat) * 30.0 / 3.1416;\n  float land = step(.5, fbm(vec2(lon * 1.6, lat * 2.4) + 3.0)), dt = smoothstep(.3, .14, length(fract(g) - .5));\n  c += mix(B * .22, A, land) * dt * (.25 + .75 * max(0.0, dot(n, normalize(vec3(-.5, .5, .8))))); }\no = vec4(c, 1);"],
["webgl","s7","Plaine de points · événement","Grille de points en perspective, soulevée par une vague. Donne de la profondeur à une page de conférence ou de produit data.",5,"wd","Shaders","vec3 c = vec3(.015) + A * .08 * exp(-abs(p.y - .3) * 6.0);\nif (p.y < .3) { float z = .6 / (.3 - p.y); vec2 g = vec2(p.x * z, z + t * .8);\n  float h = .3 * sin(g.x * .7 + t) * cos(g.y * .5) + .25 * (fbm(g * .3) - .5);\n  float dt = smoothstep(.2, .1, length(fract(g * 2.0) - .5)) * smoothstep(14.0, 2.0, z);\n  c += mix(B, A, clamp(h * 2.0 + .5, 0.0, 1.0)) * dt * (.35 + h * 2.2); }\no = vec4(c, 1);"],
["webgl","s8","Champ ASCII · outil développeur","Le même bruit qu'un fond fluide, rendu en caractères. Signal immédiat « terminal » pour une CLI ou une base de données.",5,"wd","Shaders","vec2 cell = floor(gl_FragCoord.xy / 8.0), cp = (2.0 * (cell * 8.0 + 4.0) - R) / min(R.x, R.y);\nfloat v = clamp((fbm(cp * 1.4 + vec2(t * .15, -t * .1)) - .3) * 2.4, 0.0, 1.0);\nint n = v > .85 ? 11512810 : v > .7 ? 13199452 : v > .55 ? 15255086 : v > .4 ? 332772 : v > .25 ? 65600 : v > .1 ? 4096 : 0;\no = vec4(vec3(.015) + mix(B * .6, A, v) * ch(n, mod(gl_FragCoord.xy / 4.0, 2.0) - 1.0), 1);"],
["webgl","s12","Fils de soie · produit audio","Six lignes lumineuses portées par un champ de bruit. Lecture « son, onde, flux » : musique, podcast, streaming.",5,"wd","Shaders","vec3 c = vec3(0);\nfor (int i = 0; i < 6; i++) { float k = float(i); float y = p.y - .3 * sin(p.x * 1.3 + t * .4 + k * .6) - (k - 2.5) * .07 - .3 * (fbm(vec2(p.x * .8 + t * .1, k)) - .5);\n  c += mix(A, B, k / 5.0) * .01 / abs(y); }\no = vec4(1.0 - exp(-c - .015), 1);"],
["webgl","s9","Révélation au pointeur · studio créatif","Fond monochrome ; la couleur apparaît dans une tache d'encre qui suit la souris. Survolez la maquette (fonctionne aussi en pause).",5,"wd","Shaders","float base = fbm(p * 2.0 + t * .05); vec3 col = mix(A, B, fbm(p * 3.0 - t * .1)) * (.35 + base);\nfloat m = smoothstep(.45, .15, length(p - M) + (fbm(p * 6.0 + t * .3) - .5) * .35);\no = vec4(mix(vec3(base * .32 + .02), col, m), 1);"],
["webgl","s10","Holographique · carte membre","Bandes irisées qui glissent avec le pointeur, fines stries, reflet. Pour une offre premium, une carte, un billet collector.",5,"wd","Shaders","float g = dot(p, normalize(vec2(1, .6))) * 3.0 + M.x * 2.0 + M.y + t * .15;\nvec3 h = .5 + .5 * cos(6.2832 * (g * .35 + vec3(0, .33, .67)));\nfloat ln = .5 + .5 * sin((p.x + p.y) * 70.0), sp = exp(-length(p - M * .9) * 2.2);\no = vec4(mix(mix(vec3(.12), h, .5 + .15 * ln) * (.6 + sp * .9), A, .18), 1);"],
["webgl","s14","Particules · héros IA","Deux couches de points qui dérivent ; ils s'écartent autour du curseur. Survolez la maquette.",5,"wd","Shaders","vec2 d = p - M; vec2 q = p - normalize(d + 1e-4) * .18 * exp(-dot(d, d) * 5.0);\nvec3 c = vec3(.012);\nfor (int L = 0; L < 2; L++) { float s = L == 0 ? 14.0 : 7.0; vec2 g = q * s + vec2(t * (.15 + .1 * float(L)), t * .05), id = floor(g);\n  vec2 j = vec2(hash(id), hash(id + 7.3)), pos = .5 + .38 * sin(t * (.4 + j) + j * 6.28);\n  float r = length(fract(g) - pos), sz = .06 + .08 * hash(id + 3.1);\n  c += mix(A, B, j.x) * smoothstep(sz, sz * .3, r) * (L == 0 ? .7 : 1.0); }\no = vec4(c + A * .12 * exp(-dot(d, d) * 3.0), 1);"],
["webgl","s15","Vagues de lignes · agence","Lignes empilées qui ondulent ; le curseur soulève une colline sous lui. Survolez la maquette.",5,"wd","Shaders","vec2 d = p - M; float h = .12 * sin(p.x * 2.2 + t * .7) + .06 * sin(p.x * 5.0 - t * 1.1) + .28 * exp(-dot(d, d) * 5.0);\nfloat f = (p.y - h * (1.2 - p.y * .4)) * 14.0, ln = smoothstep(.38, .47, abs(fract(f) - .5));\no = vec4(vec3(.012) + mix(B, A, clamp(h * 2.5 + .3, 0.0, 1.0)) * ln * (.35 + .65 * smoothstep(-1.0, .6, p.y)), 1);"],
["webgl","s16","Ondes · marque bien-être","Cercles qui partent du curseur, comme une goutte sur l'eau. Survolez la maquette.",5,"wd","Shaders","float r = length(p - M), w = sin(r * 34.0 - t * 4.0) * exp(-r * 2.2);\nvec2 q = p + normalize(p - M + 1e-4) * w * .03; vec3 c = mix(B * .35, A * .55, .5 + .5 * sin(q.x * 1.4 + q.y * 1.8 + t * .2));\no = vec4(c + w * .12 + pow(max(w, 0.0), 6.0) * .5, 1);"],
["webgl","s13","Taches douces · mode clair","Formes colorées floues sur fond papier, grain léger. Le seul shader clair : bien-être, éducation, produit grand public.",5,"wd","Shaders","float v = 0.0;\nfor (int i = 0; i < 4; i++) { float k = float(i); vec2 c = .75 * vec2(sin(t * .2 + k * 1.7), cos(t * .17 + k * 2.3)); v += .35 / (1.0 + 10.0 * dot(p - c, p - c)); }\nvec3 c = mix(vec3(.96, .95, .92), mix(A, B, .5 + .5 * sin(v * 4.0 + t * .2)), smoothstep(.1, .65, v));\no = vec4(c + (hash(gl_FragCoord.xy + fract(t) * 57.0) - .5) * .06, 1);"]];
